let saved=[];try{saved=JSON.parse(localStorage.getItem('karin-selection')||'[]');if(!Array.isArray(saved))saved=[]}catch{}const allowed=['كريم Leave In','بودرة الشعر','لون الشعر'];saved=saved.filter(x=>allowed.includes(x));const count=document.querySelector('#count'),pd=document.querySelector('#productDialog'),ld=document.querySelector('#listDialog');let selected='';function update(){count.textContent=saved.length;try{localStorage.setItem('karin-selection',JSON.stringify(saved))}catch{}}update();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.product').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)});document.querySelectorAll('[data-name]').forEach(b=>b.onclick=()=>{selected=b.dataset.name;document.querySelector('#dialogTitle').textContent=selected;document.querySelector('#save').textContent=saved.includes(selected)?'موجود في اختياراتك':'أضيفي لقائمة اختياراتي';pd.showModal()});document.querySelector('#save').onclick=()=>{if(!saved.includes(selected))saved.push(selected);update();pd.close()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());function render(){const el=document.querySelector('#savedList');el.replaceChildren();(saved.length?saved:['لسه ما اخترتيش منتجات.']).forEach(n=>{const p=document.createElement('p');p.textContent=n;el.append(p)})}document.querySelector('#bag').onclick=()=>{render();ld.showModal()};document.querySelector('#clear').onclick=()=>{saved=[];update();render()};
